146	    /** A function, or a functional method with its self among the arguments: self goes first. */
147	    public FValue applyToArgs(List<FValue> args) {
148	        if (selfAt <= 0) return call(args);
149	        List<FValue> all = new ArrayList<FValue>(args);
150	        all.add(0, all.remove(selfAt));
151	        return call(all);
152	    }
153	
154	    /** A dotted method: self first. */
155	    public FValue applyMethod(FObject self, List<FValue> args) {
156	        List<FValue> all = new ArrayList<FValue>(args.size() + 1);
157	        all.add(self);
158	        all.addAll(args);
159	        return call(all);
